/**
 * Placeholder branded ids for `can()` calls about rows that do not exist yet.
 *
 * `PermissionResource` is a closed discriminated union, so asking "may this
 * actor create an issue in this project?" still has to name an `issueId`. The
 * ownership escalations inside `can()` compare ids for equality, and an empty
 * string never matches a real ULID — so a create check falls through to the
 * role matrix, which is exactly the intent.
 */

import type {
  CommentId,
  IssueId,
  MemberId,
  OrgId,
  ProjectId,
} from "@/types/common";

export const PENDING_ISSUE_ID = "" as IssueId;
export const PENDING_PROJECT_ID = "" as ProjectId;
export const PENDING_COMMENT_ID = "" as CommentId;
export const PENDING_MEMBER_ID = "" as MemberId;

/**
 * Bucket owner for rate limits consumed before any tenant is known — the login
 * and password-reset flows, which are reachable without a session.
 */
export const ANONYMOUS_ORG_ID = "" as OrgId;
/**
 * Error types raised by Server Actions that are *expected* failures rather
 * than bugs. Each one carries the `ErrorCode` that `toAppError()` maps into
 * the `AppErrorShape` the client form layer renders, mirroring the convention
 * already used by `PermissionDeniedError` and `TenantScopeError`.
 *
 * These live in `src/actions/_lib` because only the action layer produces
 * them — services throw their own domain errors, and repositories throw none.
 */

import type { LimitedResource } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";
import type { PermissionAction } from "@/types/permission";

/** No session at all, or a session whose active organization is gone. */
export class UnauthorizedActionError extends Error {
  readonly code = "unauthorized" as const;

  constructor(message = "Sign in to continue.") {
    super(message);
    this.name = "UnauthorizedActionError";
  }
}

/**
 * `can()` returned false. Distinct from `PermissionDeniedError` (thrown by
 * `assertCan()` inside services) only in that the action layer already knows
 * the action name and does not need the full `PermissionDecision`.
 */
export class ForbiddenActionError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly action: PermissionAction) {
    super(`Permission denied: ${action}`);
    this.name = "ForbiddenActionError";
  }
}

/** A plan quota from `@/config/plan-limits` would be breached. */
export class PlanLimitError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly resource: LimitedResource,
    readonly limit: number,
    readonly used: number,
  ) {
    super(`Plan limit reached for ${resource}: ${used}/${limit}`);
    this.name = "PlanLimitError";
  }
}

/** The token bucket in `@/lib/rate-limit` refused the request. */
export class RateLimitedError extends Error {
  readonly code = "rate_limited" as const;

  constructor(
    readonly bucketKey: string,
    readonly resetAt: IsoTimestamp,
  ) {
    super(`Rate limit exceeded for ${bucketKey}; retry after ${resetAt}`);
    this.name = "RateLimitedError";
  }
}

/** A feature flag that gates the whole action is off for this organization. */
export class FeatureUnavailableError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly flag: string) {
    super(`Feature not available: ${flag}`);
    this.name = "FeatureUnavailableError";
  }
}

/** The row the action addresses does not exist inside the actor's tenant. */
export class ActionNotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(readonly what: string) {
    super(`Not found: ${what}`);
    this.name = "ActionNotFoundError";
  }
}
/**
 * Maps thrown domain errors onto `AppErrorShape`.
 *
 * The service layer throws (`PermissionDeniedError`, `TenantScopeError`,
 * `FeatureDisabledError`, `AlreadyArchivedError`, `InvalidSlugError`,
 * `ZodError`); Server Actions and Route Handlers never propagate those to the
 * client. Everything funnels through `toAppError()` so one thrown class maps
 * to exactly one `ErrorCode` and one HTTP status, app-wide.
 */
import { FeatureDisabledError } from "@/lib/feature-flags";
import { PermissionDeniedError } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import type { ActionResult, AppErrorShape, ErrorCode } from "@/types/api";
import { ZodError, type ZodIssue } from "zod";

export const HTTP_STATUS_BY_CODE: Readonly<Record<ErrorCode, number>> = {
  unauthorized: 401,
  forbidden: 403,
  not_found: 404,
  validation_failed: 422,
  conflict: 409,
  rate_limited: 429,
  plan_limit_exceeded: 402,
  tenant_scope_violation: 403,
  internal_error: 500,
};

/** True for the error classes this module knows how to translate faithfully. */
export function isDomainError(error: unknown): boolean {
  return (
    error instanceof PermissionDeniedError ||
    error instanceof TenantScopeError ||
    error instanceof FeatureDisabledError ||
    error instanceof AlreadyArchivedError ||
    error instanceof InvalidSlugError ||
    error instanceof ZodError
  );
}

/** Collapses a `ZodError` into the `field → messages` map forms consume. */
export function fieldErrorsFromZod(
  error: ZodError,
): Readonly<Record<string, readonly string[]>> {
  const fields: Record<string, string[]> = {};
  for (const issue of error.issues as readonly ZodIssue[]) {
    const key = issue.path.length === 0 ? "_root" : issue.path.join(".");
    (fields[key] ??= []).push(issue.message);
  }
  return fields;
}

export function toAppError(error: unknown): AppErrorShape {
  if (error instanceof ZodError) {
    return {
      code: "validation_failed",
      message: "Please correct the highlighted fields.",
      fieldErrors: fieldErrorsFromZod(error),
    };
  }

  if (error instanceof PermissionDeniedError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: {
        action: error.action,
        resourceKind: error.decision.resourceKind,
        reason: error.decision.reason,
      },
    };
  }

  if (error instanceof TenantScopeError) {
    return {
      code: "tenant_scope_violation",
      message: "That resource belongs to a different organization.",
      meta: { expectedOrgId: error.expectedOrgId, actualOrgId: error.actualOrgId },
    };
  }

  if (error instanceof FeatureDisabledError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: { flag: error.flag },
    };
  }

  if (error instanceof AlreadyArchivedError) {
    return {
      code: "conflict",
      message: error.message,
      meta: { entity: error.entity, id: error.id },
    };
  }

  if (error instanceof InvalidSlugError) {
    return {
      code: "validation_failed",
      message: error.message,
      fieldErrors: { slug: [error.message] },
      meta: { value: error.value },
    };
  }

  return {
    code: "internal_error",
    message:
      error instanceof Error ? error.message : "Something went wrong. Try again.",
  };
}

/** The failure envelope a Server Action returns instead of throwing. */
export function toActionResult(error: unknown): ActionResult<never> {
  return {
    ok: false,
    error: toAppError(error),
    submittedAt: new Date().toISOString(),
  };
}
/**
 * Renders react-email templates and 'sends' them by writing the draft to the log. No network egress.
 */
import { createLogger } from "@/lib/logger";

export type OutgoingEmail = {
  to: string;
  subject: string;
  html: string;
  text: string;
};

export type RenderedEmail = { subject: string; html: string; text: string };

export type EmailTemplate =
  | "invite"
  | "digest"
  | "mention"
  | "invoice"
  | "welcome"
  | "password-reset"
  | "overdue";

const logger = createLogger("email-service");

/** Subject lines per template; the props fill in the bracketed parts. */
const SUBJECTS: Readonly<Record<EmailTemplate, string>> = {
  invite: "You have been invited to a Taskflow workspace",
  digest: "Your Taskflow digest",
  mention: "You were mentioned in Taskflow",
  invoice: "Your Taskflow invoice",
  welcome: "Welcome to Taskflow",
  "password-reset": "Reset your Taskflow password",
  overdue: "You have overdue issues",
};

/**
 * "Sends" a message. Taskflow has no outbound mail transport by design — the
 * corpus must build and run offline — so delivery means writing the draft to
 * the structured log, where the dev tools tab surfaces it.
 */
export async function sendEmail(message: OutgoingEmail): Promise<void> {
  logger.info("email.sent", {
    to: message.to,
    subject: message.subject,
    bytes: message.html.length,
  });
}

/**
 * Renders a template to both an HTML and a plain-text body. The text half is
 * derived from the HTML rather than written twice, so the two can never drift.
 */
export async function renderEmail(
  template: EmailTemplate,
  props: Readonly<Record<string, unknown>>,
): Promise<RenderedEmail> {
  const subject = subjectFor(template, props);
  const html = renderBody(template, props);

  return { subject, html, text: toPlainText(html) };
}

function subjectFor(
  template: EmailTemplate,
  props: Readonly<Record<string, unknown>>,
): string {
  const base = SUBJECTS[template];
  const orgName = props.orgName;
  return typeof orgName === "string" ? `${base} — ${orgName}` : base;
}

function renderBody(
  template: EmailTemplate,
  props: Readonly<Record<string, unknown>>,
): string {
  const rows = Object.entries(props)
    .filter(([, value]) => value !== null && value !== undefined)
    .map(
      ([key, value]) =>
        `<tr><td>${escapeHtml(key)}</td><td>${escapeHtml(String(value))}</td></tr>`,
    )
    .join("");

  return [
    `<html><body><h1>${escapeHtml(SUBJECTS[template])}</h1>`,
    `<table>${rows}</table>`,
    "</body></html>",
  ].join("");
}

function toPlainText(html: string): string {
  return html
    .replace(/<\/(?:tr|h1|p|div)>/g, "\n")
    .replace(/<[^>]+>/g, " ")
    .replace(/[ \t]+/g, " ")
    .replace(/\n\s+/g, "\n")
    .trim();
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}
/**
 * Renders a react-email component to the `{ subject, html, text }` triple
 * `EmailService` sends.
 *
 * `EmailTemplate` is the closed vocabulary of templates; this module is the
 * only place that maps a name to a component and to a subject line, so
 * adding a template means touching exactly one switch in each direction.
 */
import { render } from "@react-email/components";
import { createElement, type ReactElement } from "react";
import { SITE_CONFIG } from "@/config/site";
import type {
  EmailTemplate,
  RenderedEmail,
} from "@/server/services/email-service";
import { DigestEmail, type DigestEmailProps } from "./digest-email";
import { InviteEmail, type InviteEmailProps } from "./invite-email";
import { InvoiceEmail, type InvoiceEmailProps } from "./invoice-email";
import { MentionEmail, type MentionEmailProps } from "./mention-email";
import { OverdueEmail, type OverdueEmailProps } from "./overdue-email";
import {
  PasswordResetEmail,
  type PasswordResetEmailProps,
} from "./password-reset-email";
import { WelcomeEmail, type WelcomeEmailProps } from "./welcome-email";

type Props = Readonly<Record<string, unknown>>;

/** Reads a string prop defensively — templates are fed loosely typed payloads. */
function str(props: Props, key: string, fallback = ""): string {
  const value = props[key];
  return typeof value === "string" && value !== "" ? value : fallback;
}

function count(props: Props, key: string): number {
  const value = props[key];
  return Array.isArray(value) ? value.length : 0;
}

function elementFor(template: EmailTemplate, props: Props): ReactElement {
  switch (template) {
    case "invite":
      return createElement(InviteEmail, props as unknown as InviteEmailProps);
    case "digest":
      return createElement(DigestEmail, props as unknown as DigestEmailProps);
    case "mention":
      return createElement(MentionEmail, props as unknown as MentionEmailProps);
    case "invoice":
      return createElement(InvoiceEmail, props as unknown as InvoiceEmailProps);
    case "welcome":
      return createElement(WelcomeEmail, props as unknown as WelcomeEmailProps);
    case "password-reset":
      return createElement(
        PasswordResetEmail,
        props as unknown as PasswordResetEmailProps,
      );
    case "overdue":
      return createElement(OverdueEmail, props as unknown as OverdueEmailProps);
  }
}

/** The subject line for a template, derived from the same props as the body. */
export function subjectFor(template: EmailTemplate, props: Props): string {
  switch (template) {
    case "invite":
      return `${str(props, "inviterName", "Someone")} invited you to ${str(
        props,
        "orgName",
        SITE_CONFIG.name,
      )}`;
    case "digest": {
      const total = count(props, "entries");
      return `Your ${str(props, "orgName", SITE_CONFIG.name)} digest — ${total} update${
        total === 1 ? "" : "s"
      }`;
    }
    case "mention":
      return `${str(props, "actorName", "Someone")} mentioned you on "${str(
        props,
        "issueTitle",
        "an issue",
      )}"`;
    case "invoice":
      return `Invoice ${str(props, "invoiceNumber", "")} for ${str(
        props,
        "orgName",
        SITE_CONFIG.name,
      )}`.replace(/\s+/g, " ");
    case "welcome":
      return `Welcome to ${SITE_CONFIG.name}`;
    case "password-reset":
      return `Reset your ${SITE_CONFIG.name} password`;
    case "overdue": {
      const total = count(props, "issues");
      return `${total} overdue issue${total === 1 ? "" : "s"} in ${SITE_CONFIG.name}`;
    }
  }
}

/** Renders both the HTML and the plain-text alternative in one pass. */
export async function renderTemplate(
  template: EmailTemplate,
  props: Props,
): Promise<RenderedEmail> {
  const element = elementFor(template, props);
  const [html, text] = await Promise.all([
    render(element),
    render(element, { plainText: true }),
  ]);

  return { subject: subjectFor(template, props), html, text };
}
