sub(p,'import { eq, lt } from "drizzle-orm";','import { eq, lte } from "drizzle-orm";')
sub(p,'''/**
 * Housekeeping sweep; returns how many rows it removed. A row that predates
 * the sweep is stale by definition — the cookie is re-issued on every sign-in,
 * so anything older than `now` has been superseded.
 */
export async function purgeExpiredSessions(
  now: IsoTimestamp,
): Promise<number> {
  const rows = getDb()
    .delete(sessions)
    .where(lt(sessions.createdAt, now))
    .returning({ id: sessions.id })
    .all();
  return rows.length;
}''','''/**
 * Revokes the one session a cookie token identifies. Unknown and already
 * revoked tokens match no row, so signing out twice is harmless.
 *
 * Not in the manifest: `SessionPrincipal` carries no session id, and the token
 * hash is the only handle the sign-out path holds.
 */
export async function revokeSessionByTokenHash(
  tokenHash: string,
): Promise<void> {
  getDb().delete(sessions).where(eq(sessions.tokenHash, tokenHash)).run();
}

/**
 * Revokes every session of one user — a password reset must sign out every
 * device that was using the old password. Returns how many rows it removed.
 */
export async function revokeSessionsForUser(userId: UserId): Promise<number> {
  const rows = getDb()
    .delete(sessions)
    .where(eq(sessions.userId, userId))
    .returning({ id: sessions.id })
    .all();
  return rows.length;
}

/**
 * Housekeeping sweep; returns how many rows it removed. Only rows whose expiry
 * has passed as of `now` are removed — the same boundary
 * `findSessionByTokenHash` uses — so live sessions are never touched.
 */
export async function purgeExpiredSessions(
  now: IsoTimestamp,
): Promise<number> {
  const rows = getDb()
    .delete(sessions)
    .where(lte(sessions.expiresAt, now))
    .returning({ id: sessions.id })
    .all();
  return rows.length;
}''')

