const SESSION_TTL_DAYS = 30;
const MS_PER_DAY = 24 * 60 * 60 * 1000;
''','''const MS_PER_HOUR = 60 * 60 * 1000;

/** Lifetime of an ordinary sign-in: short, so a shared computer forgets it. */
const SESSION_TTL_MS = 24 * MS_PER_HOUR;

/** Lifetime of a sign-in that asked to be remembered. */
const REMEMBERED_SESSION_TTL_MS = 30 * 24 * MS_PER_HOUR;
''')
