  );
''','''/**
 * Mints a session. Only the hash reaches the database, so a dump of the
 * `sessions` table cannot be replayed as a login.
 *
 * The session lasts 24 hours unless `rememberMe` is set, in which case it
 * lasts 30 days.
 */
export async function createSessionToken(
  userId: UserId,
  options: { readonly rememberMe?: boolean } = {},
): Promise<{ token: string; expiresAt: IsoTimestamp }> {
  const token = randomToken(TOKEN_BYTES);
  const ttlMs =
    options.rememberMe === true ? REMEMBERED_SESSION_TTL_MS : SESSION_TTL_MS;
  const expiresAt = toIsoTimestamp(new Date(Date.now() + ttlMs));
''')
