 * cookie is dropped by the caller either way.
 */
export async function destroySession(token: string): Promise<void> {
  const principal = await resolveSession(token);
  if (!principal) return;

  await sessionRepo.purgeExpiredSessions(toIsoTimestamp(new Date()));
}''','''/**
 * Logs a session out by deleting the one row its token identifies. Every other
 * session — the same user's other devices and everyone else's — is untouched,
 * and an unknown or already-ended token is a no-op.
 */
export async function destroySession(token: string): Promise<void> {
  await sessionRepo.revokeSessionByTokenHash(hashToken(token));
}''')

