sub(p,'''export function getBucketConfig(bucketKey: string): RateLimitConfig {
  return RATE_LIMIT_BUCKETS[bucketKey] ?? DEFAULT_BUCKET;
}''','''/**
 * A bucket key may carry a subject after the declared name — the sign-in and
 * password-reset limiters key by address (`auth:password-reset:<email>`) so
 * one account's attempts never spend another's allowance. Such a key keeps
 * the shape declared for its base bucket; the longest declared prefix wins.
 */
export function getBucketConfig(bucketKey: string): RateLimitConfig {
  const exact = RATE_LIMIT_BUCKETS[bucketKey];
  if (exact) return exact;

  let match: string | null = null;
  for (const declared of Object.keys(RATE_LIMIT_BUCKETS)) {
    if (
      bucketKey.startsWith(`${declared}:`) &&
      (match === null || declared.length > match.length)
    ) {
      match = declared;
    }
  }

  return (match === null ? undefined : RATE_LIMIT_BUCKETS[match]) ?? DEFAULT_BUCKET;
}''')

