ROOT="$PWD"; mkdir -p /tmp/authcheck && cat > /tmp/authcheck/vitest.config.ts <<EOF
import { defineConfig } from "vitest/config";
export default defineConfig({
  root: "$ROOT",
  resolve: { alias: { "@": "$ROOT/src", "~tests": "$ROOT/tests" } },
  server: { fs: { strict: false } },
  test: { environment: "node", globals: true, include: ["/tmp/authcheck/*.test.ts"] },
});
EOF
cat > /tmp/authcheck/auth.test.ts <<'EOF'
import { afterAll, afterEach, beforeAll, beforeEach, expect, it, vi } from "vitest";

const sent: { to: string; token: string }[] = [];
vi.mock("@/server/services/email-service", async (orig) => {
  const real = await orig<typeof import("@/server/services/email-service")>();
  return {
    ...real,
    renderEmail: async (t: string, props: Record<string, unknown>) => {
      if (t === "password-reset") sent.push({ to: "", token: String(props.token) });
      return real.renderEmail(t as never, props);
    },
  };
});

import { resetRateLimits, getBucketConfig } from "@/lib/rate-limit";
import * as auth from "@/server/services/auth-service";
import * as sessions from "@/server/services/session-service";
import * as userRepo from "@/server/repositories/user-repository";
import { hashPassword } from "@/lib/hash";
import { getDb, sessions as sessionsTable } from "@/server/db";
import { useTemporaryDatabase } from "~tests/server/_support/fixtures";

let cleanup: () => void;
let n = 0;
const PW = "Correct-Horse-1234";
async function mkUser() {
  n += 1;
  const email = `user${n}@example.com`;
  const user = await userRepo.insertUser({ email, name: `U${n}`, passwordHash: await hashPassword(PW) });
  return { user, email };
}
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
beforeEach(() => { resetRateLimits(); sent.length = 0; });
afterEach(() => vi.useRealTimers());

it("logout only ends that session", async () => {
  const a = await mkUser(); const b = await mkUser();
  const a1 = await auth.login({ email: a.email, password: PW, rememberMe: false });
  const a2 = await auth.login({ email: a.email.toUpperCase(), password: PW, rememberMe: false });
  const b1 = await auth.login({ email: b.email, password: PW, rememberMe: false });
  await sessions.destroySession(a1.token);
  await sessions.destroySession(a1.token);
  await sessions.destroySession("nonexistent-token");
  expect(await sessions.resolveSession(a1.token)).toBeNull();
  expect(await sessions.resolveSession(a2.token)).not.toBeNull();
  expect(await sessions.resolveSession(b1.token)).not.toBeNull();
  const a3 = await auth.login({ email: a.email, password: PW, rememberMe: false });
  expect(await sessions.resolveSession(a3.token)).not.toBeNull();
  const rows = getDb().select().from(sessionsTable).all();
  const before = rows.length;
  await auth.logout(rows[0]!.id as never);
  await auth.logout("01ARZ3NDEKTSV4RRFFQ69G5FAV" as never);
  expect(getDb().select().from(sessionsTable).all().length).toBe(before - 1);
});

it("remember me controls lifetime", async () => {
  vi.useFakeTimers({ toFake: ["Date"] });
  vi.setSystemTime(new Date("2026-03-15T12:00:00.000Z"));
  const a = await mkUser();
  const short = await auth.login({ email: a.email, password: PW, rememberMe: false });
  const long = await auth.login({ email: a.email, password: PW, rememberMe: true });
  vi.setSystemTime(new Date("2026-03-16T11:59:00.000Z"));
  expect(await sessions.resolveSession(short.token)).not.toBeNull();
  vi.setSystemTime(new Date("2026-03-16T12:00:01.000Z"));
  expect(await sessions.resolveSession(short.token)).toBeNull();
  expect(await sessions.resolveSession(long.token)).not.toBeNull();
  vi.setSystemTime(new Date("2026-04-14T11:59:00.000Z"));
  expect(await sessions.resolveSession(long.token)).not.toBeNull();
  vi.setSystemTime(new Date("2026-04-14T12:00:01.000Z"));
  expect(await sessions.resolveSession(long.token)).toBeNull();
});

it("reset links: 60 min, single use, retire older, end sessions", async () => {
  vi.useFakeTimers({ toFake: ["Date"] });
  vi.setSystemTime(new Date("2026-03-15T12:00:00.000Z"));
  const a = await mkUser(); const b = await mkUser();
  const sa = await auth.login({ email: a.email, password: PW, rememberMe: true });
  const sb = await auth.login({ email: b.email, password: PW, rememberMe: true });
  await auth.requestPasswordReset({ email: "nobody@example.com" });
  expect(sent.length).toBe(0);
  await auth.requestPasswordReset({ email: a.email.toUpperCase() });
  await auth.requestPasswordReset({ email: b.email });
  await auth.requestPasswordReset({ email: a.email });
  const [a1, b1, a2] = sent.map((s) => s.token);
  const NEW = "Brand-New-Pass-9876";
  await expect(auth.confirmPasswordReset({ token: a1!, password: NEW, confirmPassword: NEW })).rejects.toThrow(/no longer valid/);
  vi.setSystemTime(new Date("2026-03-15T12:59:00.000Z"));
  await auth.confirmPasswordReset({ token: a2!, password: NEW, confirmPassword: NEW });
  await expect(auth.confirmPasswordReset({ token: a2!, password: "Other-Pass-123456", confirmPassword: "Other-Pass-123456" })).rejects.toThrow(/no longer valid/);
  expect(await sessions.resolveSession(sa.token)).toBeNull();
  expect(await sessions.resolveSession(sb.token)).not.toBeNull();
  await expect(auth.login({ email: a.email, password: PW, rememberMe: false })).rejects.toThrow(/did not match/);
  await auth.login({ email: a.email, password: NEW, rememberMe: false });
  vi.setSystemTime(new Date("2026-03-15T13:00:01.000Z"));
  await expect(auth.confirmPasswordReset({ token: b1!, password: NEW, confirmPassword: NEW })).rejects.toThrow(/no longer valid/);
  await auth.login({ email: b.email, password: PW, rememberMe: false });
});

it("limits are per address", async () => {
  vi.useFakeTimers({ toFake: ["Date"] });
  vi.setSystemTime(new Date("2026-03-15T12:00:00.000Z"));
  const a = await mkUser(); const b = await mkUser();
  const cap = getBucketConfig("auth:login").capacity;
  for (let i = 0; i < cap; i += 1) {
    await expect(auth.login({ email: i % 2 ? a.email : a.email.toUpperCase(), password: "wrong", rememberMe: false })).rejects.toThrow(/did not match/);
  }
  await expect(auth.login({ email: a.email, password: PW, rememberMe: false })).rejects.toThrow(/Too many/);
  await auth.login({ email: b.email, password: PW, rememberMe: false });
  // throttled account can still reset
  await auth.requestPasswordReset({ email: a.email });
  expect(sent.length).toBe(1);
  const NEW = "Brand-New-Pass-9876";
  await auth.confirmPasswordReset({ token: sent[0]!.token, password: NEW, confirmPassword: NEW });
  vi.setSystemTime(new Date("2026-03-15T12:10:00.000Z"));
  await auth.login({ email: a.email, password: NEW, rememberMe: false });

  // reset requests per address
  sent.length = 0;
  const rcap = getBucketConfig("auth:password-reset").capacity;
  expect(getBucketConfig("auth:password-reset:x@y.z").capacity).toBe(rcap);
  for (let i = 0; i < rcap + 3; i += 1) await auth.requestPasswordReset({ email: a.email });
  expect(sent.length).toBe(rcap);
  await auth.requestPasswordReset({ email: b.email });
  expect(sent.length).toBe(rcap + 1);
  await auth.confirmPasswordReset({ token: sent[rcap - 1]!.token, password: PW, confirmPassword: PW });
});
EOF
